"""A headless terminal: drive a real interactive bash shell through a pty.

The public API is :class:`HeadlessTerminal`, a concrete implementation of
``BaseTerminal``.  It spawns a real interactive bash process attached to a
pseudo terminal (pty) so that:

* the shell behaves exactly like a terminal a human would type in
  (job control, readline, control characters, background jobs, ...),
* bash sources its startup files (``/etc/bash.bashrc``, ``~/.bashrc``, ...),
* full screen/interactive programs (vim, less, top, python REPL, ssh, ...)
  work because the child process runs on a real terminal of configurable size,
* control characters such as ``"\x03"`` (Ctrl-C), ``"\x04"`` (Ctrl-D),
  ``"\x1b"`` (Escape), arrow keys, ... are delivered to the child *raw*, so
  they are never interpreted by the caller's own terminal.

Anything else you might want from such a class (reading the terminal output,
waiting for the shell to become idle, running a command and getting its output,
resizing, killing the shell, ...) is provided as convenience methods; the
``BaseTerminal`` contract is implemented by :meth:`send_keystrokes`.
"""

import errno
import os
import re
import select
import signal
import sys
import threading
import time
from base64 import b64encode

# --------------------------------------------------------------------------- #
# Locate and import ``BaseTerminal``.
# --------------------------------------------------------------------------- #

_HERE = os.path.dirname(os.path.abspath(__file__))
if _HERE not in sys.path:
    sys.path.insert(0, _HERE)


def _load_base_terminal():
    """Import :class:`BaseTerminal`, whichever layout we are used from."""
    try:
        from base_terminal import BaseTerminal  # type: ignore
        return BaseTerminal
    except Exception:
        pass
    try:  # e.g. ``from .base_terminal import BaseTerminal`` inside a package
        from .base_terminal import BaseTerminal  # type: ignore
        return BaseTerminal
    except Exception:
        pass
    import importlib.util

    for candidate in (os.path.join(_HERE, "base_terminal.py"),
                      "/app/base_terminal.py"):
        if os.path.exists(candidate):
            spec = importlib.util.spec_from_file_location("_base_terminal", candidate)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            return module.BaseTerminal
    raise ImportError(
        "could not import BaseTerminal: expected it in 'base_terminal.py' "
        "next to headless_terminal.py"
    )


BaseTerminal = _load_base_terminal()


# --------------------------------------------------------------------------- #
# Small helpers
# --------------------------------------------------------------------------- #

_ANSI_OSC = re.compile(rb"\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)")
_ANSI_DCS = re.compile(rb"\x1b[P\x98][^\x1b]*(?:\x1b\\|\xc2\x9c)")
_ANSI_CSI = re.compile(
    rb"\x1b(?:\[[0-?]*[ -/]*[@-~]|[@-Z\\-_]|[PX^]\\[0-?]*[ -/]*[@-~])"
)
_ANSI_ESC = re.compile(rb"\x1b[@-Z\\-_]")
_ANSI_8BIT = re.compile(
    rb"[\xc2][\x80-\x9f]|[\xc9][\x80-\x8f][\x80-\xbf]"
    rb"|[\xcd][\xa0-\xbf][\x80-\xbf]|[\xce][\x80-\x8f][\x80-\xbf]"
)


def _strip_escapes(data):
    """Remove terminal control sequences from *bytes* (best effort).

    Used only for plain-text output extraction, never for what is sent to the
    terminal.
    """
    if isinstance(data, str):
        data = data.encode("utf-8", "replace")
    data = _ANSI_OSC.sub(b"", data)
    data = _ANSI_DCS.sub(b"", data)
    data = _ANSI_8BIT.sub(b"", data)
    data = _ANSI_CSI.sub(b"", data)
    data = _ANSI_ESC.sub(b"", data)
    return data


def _quote(s):
    """Quote *s* so that bash expands escape sequences (``$'...'``)."""
    out = ["$'"]
    for ch in s:
        o = ord(ch)
        if ch == "'":
            out.append("\\'")
        elif ch == "\\\\":
            out.append("\\\\\\\\")
        elif ch == "$":
            out.append("\\$")
        elif o < 32 or o == 127:
            out.append("\\%03o" % o)
        elif o > 126:
            out.append("\\U%x" % o)
        else:
            out.append(ch)
    out.append("'")
    return "".join(out)


def _find_bash():
    found = None
    for path in ("/bin/bash", "/usr/bin/bash", "/bin/ash", "/bin/sh"):
        if os.path.exists(path):
            found = path
            break
    if found is None:
        for name in ("bash", "sh"):
            for directory in os.environ.get("PATH", "").split(os.pathsep):
                candidate = os.path.join(directory, name)
                if directory and os.path.exists(candidate):
                    found = candidate
                    break
            if found:
                break
    if found is None:
        raise RuntimeError("no usable shell found (bash/sh)")
    return found


class _ChildEOF(Exception):
    pass


# --------------------------------------------------------------------------- #
# The terminal itself
# --------------------------------------------------------------------------- #


class HeadlessTerminal(BaseTerminal):
    """A headless terminal driven by typed keystrokes.

    Constructing it starts an interactive bash shell on a fresh pty.  From then
    on :meth:`send_keystrokes` writes to that pty exactly like typing on a
    keyboard.
    """

    DEFAULT_ROWS = 24
    DEFAULT_COLS = 80
    DEFAULT_PROMPT = "$ "
    # maximum time (seconds) to wait for the shell to be ready/accept input
    READY_TIMEOUT = 20.0
    # how much raw output we keep around for text searches
    BUFFER_LIMIT = 400000
    SCREEN_ROWS = 80   # emulated screen height (rows) used when resizing
    SCREEN_COLS = 200  # emulated screen width (columns)

    def __init__(self, rows=None, cols=None, cwd=None, env=None, term=None,
                 shell=None, prompt=None, track_screen=None, **kwargs):
        super().__init__(**kwargs)
        self.rows = int(rows) if rows else self.DEFAULT_ROWS
        self.cols = int(cols) if cols else self.DEFAULT_COLS
        if track_screen is None:
            track_screen = (self.rows, self.cols) != (self.SCREEN_ROWS, self.SCREEN_COLS)
        self._track_screen = bool(track_screen)
        self._cwd = cwd or os.getcwd()
        self._env_overrides = dict(env) if env else {}
        self.term = term or os.environ.get("TERM") or "xterm-256color"
        self.shell_path = shell or _find_bash()
        self._prompt_request = prompt
        if self._prompt_request is None:
            self._prompt_text = self.DEFAULT_PROMPT
            self._fixed_prompt = True
        else:
            self._prompt_text = str(self._prompt_request)
            self._fixed_prompt = prompt != ""

        self._lock = threading.RLock()
        self._buffer = ""
        self._reader = None
        self._stop_event = threading.Event()
        self._eof = False
        self._screen = None
        self._screen_stream = None
        self._child = None
        self._backend = None
        self._login = False
        self._marker = None          # unique prompt marker, e.g. "ht3f9a1b$ "
        self._closed = True
        self._launched = False
        self._launch()

    # ------------------------------------------------------------------ #
    # construction / teardown
    # ------------------------------------------------------------------ #
    def _launch(self):
        self._closed = False
        self._eof = False
        self._buffer = ""
        try:
            self._spawn()
            self._install_prompt()
            self._start_reader()
            self._launched = True
        except Exception:
            self._closed = True
            raise

    def _child_argv(self, login):
        if login:
            args = ["-l", "-i", "-N"]
        else:
            args = ["-i", "-N"]
        return args

    def _child_env(self):
        env = dict(os.environ)
        env["TERM"] = self.term
        env["COLUMNS"] = str(self.cols)
        env["LINES"] = str(self.rows)
        env["LANG"] = env.get("LANG") or "C.UTF-8"
        env["PS1"] = self.DEFAULT_PROMPT
        env.pop("PROMPT_COMMAND", None)
        env["TMOUT"] = ""
        env.update(self._env_overrides)
        return env

    def _spawn(self):
        errors = []
        try:
            import pexpect  # type: ignore
        except Exception as exc:  # pragma: no cover
            pexpect = None
            errors.append("pexpect: %s" % exc)
        if pexpect is not None:
            for login in (False, True):
                child = None
                try:
                    child = pexpect.spawn(
                        self.shell_path,
                        self._child_argv(login),
                        timeout=None,
                        encoding=None,
                        codec_errors=None,
                        echo=True,
                        dimensions=(self.rows, self.cols),
                        cwd=self._cwd,
                        env=self._child_env(),
                        maxread=1 << 20,
                        buffersize=1 << 20,
                        use_poll=True,
                    )
                except Exception as exc:
                    errors.append("pexpect(login=%s): %s" % (login, exc))
                    if child is not None:
                        try:
                            child.close(force=True)
                        except Exception:
                            pass
                    continue
                if not self._wait_accept_input(child):
                    errors.append("pexpect(login=%s): shell did not come up" % login)
                    try:
                        child.close(force=True)
                    except Exception:
                        pass
                    continue
                self._backend = "pexpect"
                self._login = login
                self._child = child
                # pexpect installs a SIGCHLD handler; keep it out of our way of
                # the user's code but leave the child owned by us.
                return
        # fall back to ptyprocess directly, then to the stdlib
        try:
            self._spawn_ptyprocess()
            return
        except Exception as exc:
            errors.append("ptyprocess: %s" % exc)
        self._spawn_stdlib()

    def _spawn_ptyprocess(self):
        import ptyprocess  # type: ignore

        for login in (False, True):
            child = ptyprocess.PtyProcessUnicode.spawn(
                [self.shell_path] + self._child_argv(login),
                dimensions=(self.rows, self.cols),
                cwd=self._cwd,
                env=self._child_env(),
            )
            if self._wait_accept_input(child):
                self._backend = "ptyprocess"
                self._login = login
                self._child = child
                return
            try:
                child.terminate(force=True)
            except Exception:
                pass
        raise RuntimeError("could not start shell with ptyprocess")

    def _spawn_stdlib(self):
        """Last resort: build the pty ourselves with the standard library."""
        import pty
        import struct
        import termios

        master, slave = pty.openpty()
        pid = os.fork()
        if pid == 0:  # pragma: no cover - child process
            try:
                os.setsid()
                try:
                    import fcntl

                    fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
                except Exception:
                    pass
                os.dup2(slave, 0)
                os.dup2(slave, 1)
                os.dup2(slave, 2)
                if slave > 2:
                    os.close(slave)
                if master > 2:
                    os.close(master)
                os.environ["TERM"] = self.term
                for login in (False, True):
                    try:
                        os.execv(self.shell_path, [self.shell_path] + self._child_argv(login))
                    except Exception:
                        pass
                os._exit(127)
            except Exception:  # pragma: no cover
                os._exit(127)
        os.close(slave)
        child = _StdlibChild(pid, master)
        if not self._wait_accept_input(child):
            child.close(force=True)
            raise RuntimeError("could not start shell with the stdlib pty")
        self._backend = "stdlib"
        self._child = child

    # ------------------------------------------------------------------ #
    # prompt marker used to detect an idle shell
    # ------------------------------------------------------------------ #
    def _is_bash(self):
        return os.path.basename(self.shell_path or "").startswith("bash")

    def _install_prompt(self):
        if self._fixed_prompt and self._prompt_request is not None:
            if self._prompt_request == "":
                self._marker = ""
            else:
                self._marker = self._prompt_text
            return
        if self._fixed_prompt and self._is_bash():
            token = "ht" + b64encode(os.urandom(6)).decode(
                "ascii"
            ).rstrip("=").replace("+", "p").replace("/", "x").lower()
            ps1 = _quote(self.DEFAULT_PROMPT)
            command = "printf '%s\\r' %s" % (token, ps1.rstrip(" ") if False else _quote(self.DEFAULT_PROMPT.rstrip() + "\r"))
            self._send_raw(("PS1=%s PROMPT_COMMAND=%s\\n" % (_quote(self.DEFAULT_PROMPT.rstrip() + "\r"), _quote("printf %s" % _quote(token)))).encode())
            time.sleep(0.2)
            self._marker = token + self.DEFAULT_PROMPT.rstrip() + " "
            return
        self._marker = self._prompt_text

    # ------------------------------------------------------------------ #
    # low level io
    # ------------------------------------------------------------------ #
    def _send_raw(self, data):
        with self._lock:
            child = self._child
        if child is None:
            raise RuntimeError("terminal is not running")
        if isinstance(data, str):
            data = data.encode("utf-8", "replace")
        if not data:
            return
        try:
            child.write(data)
        except Exception as exc:
            if getattr(exc, "errno", None) in (errno.EIO, errno.EBADF):
                self._eof = True
                return
            raise

    def _read_raw(self, timeout):
        """Read bytes from the child pty. Raises _ChildEOF on end of stream."""
        with self._lock:
            child = self._child
        if child is None:
            raise _ChildEOF("no child")
        backend = self._backend
        try:
            if backend == "pexpect":
                if timeout is None:
                    data = child.read()  # blocking; only used with care
                else:
                    data = child.read_nonblocking(size=65536, timeout=timeout)
            elif backend == "ptyprocess":
                if timeout is None or timeout <= 0:
                    timeout = 0.001
                child.delaybeforeread = timeout
                data = child.read(65536)
            else:
                data = child.read(timeout)
        except _ChildEOF:
            raise
        except Exception as exc:
            message = exc.__class__.__name__
            if "TIMEOUT" in message:
                return b""
            raise _ChildEOF(str(exc))
        if not data:
            raise _ChildEOF("empty read")
        if isinstance(data, str):
            data = data.encode("utf-8", "replace")
        return data

    def _alive_child(self):
        child = self._child
        if child is None:
            return False
        try:
            if self._backend in ("pexpect", "ptyprocess"):
                return bool(child.isalive())
            return child.isalive()
        except Exception:
            return False

    def is_shell_alive(self):
        """True while the shell process is still running."""
        return self._alive_child()

    # ------------------------------------------------------------------ #
    # background reader
    # ------------------------------------------------------------------ #
    def _start_reader(self):
        self._stop_event.clear()
        thread = threading.Thread(
            target=self._reader_loop, name="headless-terminal-reader", daemon=True
        )
        self._reader = thread
        thread.start()

    def _reader_loop(self):
        screen = None
        stream = None
        if self._track_screen:
            try:
                screen = self._ensure_screen()
                stream = self._screen_stream
            except Exception:
                screen = None
        while not self._stop_event.is_set():
            try:
                data = self._read_raw(0.05)
            except _ChildEOF:
                self._eof = True
                break
            except Exception:
                if not self._alive_child():
                    self._eof = True
                break
            if not data:
                if not self._alive_child():
                    self._eof = True
                    break
                continue
            self._consume(data, screen, stream)

    def _consume(self, data, screen=None, stream=None):
        if screen is None and self._track_screen:
            try:
                screen = self._ensure_screen()
                stream = self._screen_stream
            except Exception:
                screen = None
        with self._lock:
            if screen is not None:
                try:
                    stream.feed(data.decode("utf-8", "replace"))
                except Exception:
                    pass
            text = _strip_escapes(data).decode("utf-8", "replace")
            self._buffer += text
            if len(self._buffer) > self.BUFFER_LIMIT:
                self._buffer = self._buffer[-self.BUFFER_LIMIT:]

    # ------------------------------------------------------------------ #
    # emulated screen
    # ------------------------------------------------------------------ #
    def _ensure_screen(self):
        if self._screen is not None:
            return self._screen
        import pyte  # type: ignore

        self._screen = pyte.Screen(self.SCREEN_COLS, self.SCREEN_ROWS)
        self._screen_stream = pyte.Stream(self._screen)
        return self._screen

    def read_screen(self):
        """Return the visible terminal screen as a string (one line per row)."""
        try:
            screen = self._ensure_screen()
        except Exception:
            return self.read_all_output()
        rows = [line.rstrip() for line in self._screen.display]
        while rows and not rows[-1]:
            rows.pop()
        offset = getattr(self._screen, "y", 0) - self.rows + 1
        tail = rows[offset:] if offset > 0 else rows
        tail = [row for row in tail if row]
        return "\n".join(tail)

    def cursor_position(self):
        try:
            screen = self._ensure_screen()
            return (self._screen.y, self._screen.x)
        except Exception:
            return None

    # ------------------------------------------------------------------ #
    # waiting / reading
    # ------------------------------------------------------------------ #
    def _buffer_snapshot(self):
        with self._lock:
            return self._buffer

    def read_all_output(self, clear=True, strip_escapes=True):
        """Return everything the terminal has sent since the last call."""
        with self._lock:
            text = self._buffer
            if clear:
                self._buffer = ""
        if strip_escapes:
            text = _strip_escapes(text.encode("utf-8", "replace")).decode(
                "utf-8", "replace"
            )
        return text

    def wait_for_prompt(self, timeout=30.0):
        """Wait until the shell is sitting at its prompt (idle).

        Returns True when the prompt was seen, False on timeout.
        """
        return self.wait_for_text(self._marker or self.DEFAULT_PROMPT.rstrip() + " ",
                                  timeout=timeout) is not None

    def wait_for(self, expected, timeout=30.0):
        """Wait until *expected* (str or compiled regex) shows up.

        Returns the text that was read, or None on timeout.
        """
        if isinstance(expected, str):
            needle = _strip_escapes(expected.encode("utf-8", "replace")).decode(
                "utf-8", "replace"
            )
        else:
            pattern = expected
            needle = None
        start = time.monotonic()
        while True:
            text = self._buffer_snapshot()
            if isinstance(expected, str):
                if needle in text:
                    with self._lock:
                        self._buffer = text[text.index(needle) + len(needle):]
                    return text
            else:
                match = expected.search(text)
                if match:
                    with self._lock:
                        self._buffer = text[text.end():]
                    return text
            if not self._alive_child() and self._eof:
                return None
            if time.monotonic() - start > timeout:
                return None
            time.sleep(0.02)

    def wait(self, timeout=30.0):
        """Wait until the shell process exits (or *timeout* elapses)."""
        start = time.monotonic()
        while self._alive_child():
            if time.monotonic() - start > timeout:
                return False
            time.sleep(0.02)
        return True

    def _wait_accept_input(self, child, timeout=3.0):
        """Return once the freshly spawned shell accepts input.

        Any output the shell produced (banner, motd, prompt, ...) is stored in
        our internal buffer so nothing gets lost.
        """
        end = time.monotonic() + timeout
        collected = b""
        while time.monotonic() < end:
            try:
                data = self._peek_read(child, 0.15)
            except _ChildEOF:
                return False
            if data:
                collected += data
        if not collected:
            # a shell that prints nothing at all is still fine as long as it is
            # alive and has not exited
            return True
        self._buffer += _strip_escapes(collected).decode("utf-8", "replace")
        return True

    def _peek_read(self, child, timeout):
        """Read raw bytes from *child* waiting at most *timeout*."""
        backend = self._backend
        try:
            if backend == "pexpect" or child.__class__.__module__.startswith("pexpect"):
                return child.read_nonblocking(size=65536, timeout=timeout)
            if hasattr(child, "read"):
                return child.read(timeout)
        except Exception as exc:
            if "TIMEOUT" in exc.__class__.__name__ or "EOF" in exc.__class__.__name__:
                return b""
            raise _ChildEOF(str(exc))
        return b""

    # ------------------------------------------------------------------ #
    # public API
    # ------------------------------------------------------------------ #
    def send_keystrokes(self, keystrokes, wait_sec=0.0):
        """Type *keystrokes* into the terminal.

        ``keystrokes`` is written verbatim to the terminal, so control
        characters (``"\\x03"`` -> Ctrl-C, ``"\\x04"`` -> Ctrl-D, ...) and
        escape sequences are handled by the terminal itself.  After typing, the
        terminal output produced while typing is consumed; *wait_sec* caps how
        long to spend reading/draining the terminal output afterwards.
        """
        if keystrokes is None:
            return None
        if isinstance(keystrokes, bytes):
            data = keystrokes
        else:
            data = str(keystrokes).encode("utf-8", "replace")
        self._send_raw(data)
        self._drain(time.monotonic() + max(0.0, float(wait_sec or 0.0)))
        return None

    def _drain(self, deadline):
        """Keep the internal buffer consumed until *deadline*."""
        now = time.monotonic()
        if deadline <= now:
            deadline = now + 0.03
        while time.monotonic() < deadline:
            if self._eof or not self._alive_child():
                break
            time.sleep(0.02)

    # -- convenience helpers ------------------------------------------- #
    def send_line(self, line, wait_sec=1.0, newline=True):
        """Type *line* followed by Enter (like typing a command)."""
        text = line if isinstance(line, str) else str(line)
        if newline := "\n":
            pass
        payload = (line if isinstance(line, str) else str(line))
        if not payload.endswith("\n"):
            payload += "\n"
        return self.send_keystrokes(payload, wait_sec=wait_sec)

    def run(self, command, wait_sec=30.0, timeout=None):
        """Type *command*, wait for the shell to go idle, return its output."""
        if timeout is not None:
            wait_sec = timeout
        before = len(self._buffer_snapshot())
        self.send_line(command, wait_sec=0.05)
        if not self.wait_for_prompt(timeout=wait_sec):
            raise RuntimeError(
                "command %r did not finish within %ss" % (command, wait_sec)
            )
        text = self.read_all_output()
        return self._clean_command_output(text, command)

    def _clean_command_output(self, text, command):
        # drop the echoed command and the trailing prompt
        first = text.find("\n")
        if first != -1:
            text = text[first + 1:]
        else:
            text = ""
        marker = self._marker
        if text.endswith("\r\n"):
            text = text[:-2]
        return text

    def send_key(self, key, wait_sec=0.0):
        """Send a named key, e.g. ``send_key("ctrl c")`` or ``enter``."""
        return self.send_keystrokes(self._key_to_bytes(key), wait_sec=wait_sec)

    @staticmethod
    def _key_to_bytes(key):
        name = str(key).strip()
        if len(name) > 1:
            low = name.replace("-", " ").lower()
            parts = low.split()
            if len(parts) == 2 and len(parts[1]) in (1, 3) and len(parts[0]) <= 3:
                letter = parts[1]
                if len(letter) == 1:
                    return chr((ord(letter.lower()) - 96) % 32 or 0)
                if letter in ("space", "spc"):
                    return "\x20"
            table = {
                "enter": "\r",
                "return": "\r",
                "cr": "\r",
                "newline": "\n",
                "lf": "\n",
                "tab": "\t",
                "space": " ",
                "backspace": "\x7f",
                "delete": "\x1b[3~",
                "del": "\x1b[3~",
                "escape": "\x1b",
                "esc": "\x1b",
                "escape": "\x1b",
                "escape": "\x1b",
                "escape": "\x1b",
                "up": "\x1b[A",
                "uparrow": "\x1b[A",
                "up arrow": "\x1b[A",
                "down": "\x1b[B",
                "downarrow": "\x1b[B",
                "down arrow": "\x1b[B",
                "right": "\x1b[C",
                "rightarrow": "\x1b[C",
                "right arrow": "\x1b[C",
                "left": "\x1b[D",
                "leftarrow": "\x1b[D",
                "left arrow": "\x1b[D",
                "home": "\x1b[H",
                "end": "\x1b[F",
                "pageup": "\x1b[5~",
                "pagedown": "\x1b[6~",
                "insert": "\x1b[2~",
                "break": "\x1c",
                "space": " ",
            }
            if low in table:
                return table[low]
            if low.replace(" ", "") in table:
                return table[low.replace(" ", "")]
            if len(name) > 1 and name.startswith("\\x"):
                try:
